	 */
	function totp($secret,$secretEnc,$t0,$tNow,$tStep,$numDigits,$truncOffset,$hashAlg) {
		return CkCrypt2_totp($this->_cPtr,$secret,$secretEnc,$t0,$tNow,$tStep,$numDigits,$truncOffset,$hashAlg);
	}

	/**
	 * Adds an XML certificate vault to the object's internal list of sources to be searched for certificates and private keys when encrypting/decrypting or signing/verifying.  Unlike the AddPfxSourceData and AddPfxSourceFile methods, only a single XML certificate vault can be used.  If UseCertVault is called multiple times, only the last certificate vault will be used, as each call to UseCertVault will replace the certificate vault provided in previous calls.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCrypt2Ref.html#UseCertVault
	 * @param CkXmlCertVault $vault
	 * @return bool
	 */
	function UseCertVault($vault) {
		return CkCrypt2_UseCertVault($this->_cPtr,$vault);
	}

	/**
	 * Verifies a detached digital signature against the original data contained in ARG1.  Returns _TRUE_ if the signature is verified.  The ARG2 holds a binary-encoded PKCS#7 signed-data detached signature. The type of binary encoding, such as base64, hex, or base64_mime, is determined by the EncodingMode property.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCrypt2Ref.html#VerifyBdENC
	 * @param CkBinData $data
	 * @param ?string $encodedSig
	 * @return bool
	 */
	function VerifyBdENC($data,$encodedSig) {
		return CkCrypt2_VerifyBdENC($this->_cPtr,$data,$encodedSig);
	}

	/**
	 * Verifies a detached digital signature against the original binary data.  Returns _TRUE_ if the signature is verified.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCrypt2Ref.html#VerifyBytes
	 * @param CkByteData $data
	 * @param CkByteData $sig
	 * @return bool
	 */
	function VerifyBytes($data,$sig) {
		return CkCrypt2_VerifyBytes($this->_cPtr,$data,$sig);
	}

	/**
	 * Verifies a detached digital signature against the original binary data.  Returns _TRUE_ if the signature is verified.  The ARG2 holds a binary-encoded PKCS#7 signed-data detached signature. The type of binary encoding, such as base64, hex, or base64_mime, is determined by the EncodingMode property.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCrypt2Ref.html#VerifyBytesENC
	 * @param CkByteData $data
	 * @param ?string $encodedSig
	 * @return bool
	 */
	function VerifyBytesENC($data,$encodedSig) {
		return CkCrypt2_VerifyBytesENC($this->_cPtr,$data,$encodedSig);
	}

	/**
	 * This method is the same as VerifyP7S. Applications should instead call VerifyP7S.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCrypt2Ref.html#VerifyDetachedSignature
	 * @param ?string $inFilename
	 * @param ?string $p7sFilename
	 * @return bool
	 * @deprecated
	 */
	function VerifyDetachedSignature($inFilename,$p7sFilename) {
		return CkCrypt2_VerifyDetachedSignature($this->_cPtr,$inFilename,$p7sFilename);
	}

	/**
	 * Verifies an opaque digital signature contained in a .p7m file and extracts the original data to ARG2.  Returns _TRUE_ if the .p7m is validated and the original data was extracted.  Otherwise returns _FALSE_.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCrypt2Ref.html#VerifyP7M
	 * @param ?string $p7mPath
	 * @param ?string $destPath
	 * @return bool
	 */
	function VerifyP7M($p7mPath,$destPath) {
		return CkCrypt2_VerifyP7M($this->_cPtr,$p7mPath,$destPath);
	}

	/**
	 * Verifies a detached digital signature contained in a .p7s file against the original data contained in ARG1.  Returns _TRUE_ if the signature is verified.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCrypt2Ref.html#VerifyP7S
	 * @param ?string $originalDataPath
	 * @param ?string $p7sPath
	 * @return bool
	 */
	function VerifyP7S($originalDataPath,$p7sPath) {
		return CkCrypt2_VerifyP7S($this->_cPtr,$originalDataPath,$p7sPath);
	}

	/**
	 * Verifies a detached digital signature against the original text contained in ARG1.  Returns _TRUE_ if the signature is verified.  The ARG2 holds a binary-encoded PKCS#7 signed-data detached signature. The type of binary encoding, such as base64, hex, or base64_mime, is determined by the EncodingMode property.  The Charset property determines how the text in ARG1 is converted to bytes for signature validation.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCrypt2Ref.html#VerifySbENC
	 * @param CkStringBuilder $sb
	 * @param ?string $encodedSig
	 * @return bool
	 */
	function VerifySbENC($sb,$encodedSig) {
		return CkCrypt2_VerifySbENC($this->_cPtr,$sb,$encodedSig);
	}

	/**
	 * Verifies a detached digital signature against the original text in ARG1.  Returns _TRUE_ if the signature is verified.  The ARG2 holds a binary PKCS#7 signed-data detached signature. The Charset property determines how the text in ARG1 is converted to bytes for signature validation.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCrypt2Ref.html#VerifyString
	 * @param ?string $str
	 * @param CkByteData $sig
	 * @return bool
	 */
	function VerifyString($str,$sig) {
		return CkCrypt2_VerifyString($this->_cPtr,$str,$sig);
	}

	/**
	 * Verifies a detached digital signature against the original text in ARG1.  Returns _TRUE_ if the signature is verified.  The ARG2 holds a binary-encoded PKCS#7 signed-data detached signature. The type of binary encoding, such as base64, hex, or base64_mime, is determined by the EncodingMode property.  The Charset property determines how the text in ARG1 is converted to bytes for signature validation.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCrypt2Ref.html#VerifyStringENC
	 * @param ?string $str
	 * @param ?string $encodedSig
	 * @return bool
	 */
	function VerifyStringENC($str,$encodedSig) {
		return CkCrypt2_VerifyStringENC($this->_cPtr,$str,$encodedSig);
	}

	/**
	 * Sets the XTS-AES mode data unit number.  The data unit number is a 64-bit unsigned integer.  It is passed in as two 32-bit unsigned integers representing the high and low 32-bits.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCrypt2Ref.html#XtsSetDataUnitNumber
	 * @param int $loUint32
	 * @param int $hiUint32
	 */
	function XtsSetDataUnitNumber($loUint32,$hiUint32) {
		CkCrypt2_XtsSetDataUnitNumber($this->_cPtr,$loUint32,$hiUint32);
	}

	/**
	 * Sets the XTS-AES mode tweak key from an encoded string. The encoding argument can be set to any of the following strings: base64, hex, quoted-printable, ascii, or url.  The tweak key should be equal in size to the encryption key.  For example, to do 256-bit AES-XTS, the encryption key is 256-bits, and the tweak key is also 256-bits.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCrypt2Ref.html#XtsSetEncodedTweakKey
	 * @param ?string $key
	 * @param ?string $encoding
	 */
	function XtsSetEncodedTweakKey($key,$encoding) {
		CkCrypt2_XtsSetEncodedTweakKey($this->_cPtr,$key,$encoding);
	}

	/**
	 * Sets the XTS-AES mode tweak value from an encoded string. The encoding argument can be set to any of the following strings: base64, hex, quoted-printable, ascii, or url.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCrypt2Ref.html#XtsSetEncodedTweakValue
	 * @param ?string $tweak
	 * @param ?string $encoding
	 */
	function XtsSetEncodedTweakValue($tweak,$encoding) {
		CkCrypt2_XtsSetEncodedTweakValue($this->_cPtr,$tweak,$encoding);
	}
}
